let assess,compositeWhite,headBounds,levelingAngle,rotatedSize;
let models;
async function init(){if(!models)models=(async()=>{const {FilesetResolver,FaceLandmarker,ImageSegmenter}=await import('./vendor/vision_bundle.mjs');({assess}=await import('./analysis.mjs?v=13'));({compositeWhite}=await import('./background.mjs?v=8'));({headBounds,levelingAngle,rotatedSize}=await import('./framing.mjs?v=21'));const vision=await FilesetResolver.forVisionTasks(new URL('./vendor/wasm',self.location.href).href);const face=await FaceLandmarker.createFromOptions(vision,{baseOptions:{modelAssetPath:new URL('./models/face_landmarker.task',self.location.href).href,delegate:'CPU'},runningMode:'IMAGE',numFaces:3,outputFaceBlendshapes:true,outputFacialTransformationMatrixes:true});const segment=await ImageSegmenter.createFromOptions(vision,{baseOptions:{modelAssetPath:new URL('./models/selfie_multiclass.tflite',self.location.href).href,delegate:'CPU'},runningMode:'IMAGE',outputCategoryMask:true,outputConfidenceMasks:true});return {face,segment}})();return models;}
self.onmessage=async({data})=>{const {id,bitmap,sourceWidth,sourceHeight,upscaled,makeWhite,kind}=data;try{const {face,segment}=await init();let canvas=new OffscreenCanvas(bitmap.width,bitmap.height);let ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);let faceResult=face.detect(canvas),rotation=0;if(kind==='auto-frame'){rotation=levelingAngle(faceResult,canvas.width,canvas.height);if(Math.abs(rotation)>Math.PI/9){self.postMessage({id,kind,head:{error:'Head tilt exceeds 20°. Retake with your head closer to level, or frame manually.'}});return;}if(rotation){const size=rotatedSize(bitmap.width,bitmap.height,rotation);canvas=new OffscreenCanvas(size.width,size.height);ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.fillStyle='#fff';ctx.fillRect(0,0,size.width,size.height);ctx.translate(size.width/2,size.height/2);ctx.rotate(rotation);ctx.drawImage(bitmap,-bitmap.width/2,-bitmap.height/2);ctx.setTransform(1,0,0,1,0,0);faceResult=face.detect(canvas);}}const result=segment.segment(canvas);try{if(kind==='auto-frame'){const head=headBounds(faceResult,result.categoryMask.getAsUint8Array(),result.categoryMask.width,result.categoryMask.height);self.postMessage({id,kind,head,rotation});return;}let pixels=ctx.getImageData(0,0,canvas.width,canvas.height).data,output=null,backgroundError=null;
if(makeWhite){const mask=result.confidenceMasks?.[0];if(!mask)throw new Error('Background confidence unavailable');const composed=compositeWhite(pixels,canvas.width,canvas.height,mask.getAsFloat32Array(),mask.width,mask.height);if(composed.foregroundFraction<.03||!faceResult.faceLandmarks.length)backgroundError='Could not isolate a person reliably. Try a clearer portrait, or turn off Make background white to download the original crop.';else{pixels=composed.pixels;ctx.putImageData(new ImageData(pixels,canvas.width,canvas.height),0,0);output=canvas.transferToImageBitmap();}}
const rows=assess({width:canvas.width,height:canvas.height,pixels,faceResult,mask:result.categoryMask.getAsUint8Array(),maskWidth:result.categoryMask.width,maskHeight:result.categoryMask.height,sourceWidth,sourceHeight,upscaled});if(output){const bg=rows.find(row=>row.id==='background');if(bg)bg.detail+=' Background replacement is on. Inspect hair, ears, and shoulder edges before submitting.';}self.postMessage({id,rows,output,backgroundError},output?[output]:[]);}finally{result.close();}}catch(error){models=null;self.postMessage({id,error:'Automatic analysis could not run. Your browser may not support the required on-device models, or model files could not load. You can retry or turn off background replacement to download the original crop.'});console.error(error);}finally{bitmap.close();}};
